ROOT=Path(__file__).resolve().parents[2]
STEPS_BASE='''<description/><distribute>Y</distribute><custom_distribution/><copies>1</copies><partitioning><method>none</method><schema_name/></partitioning>'''

def _target_type(task:dict):return (task.get('target_config',{}).get('type') or task.get('target') or 'POSTGRESQL').upper()

def _apply_target(xml:str,task:dict):
 if _target_type(task)!='VERTICA':return xml
 xml=xml.replace('PostgreSQL Output','Vertica Output').replace('-postgresql</name>','-vertica</name>')
 marker='<connection>ai-agents-poc</connection>'
 if marker in xml:
  head,tail=xml.rsplit(marker,1);xml=head+'<connection>vertica-poc</connection>'+tail
 return xml

def _field_type(name:str):
 if name=='customer_id' or name.endswith('_id'):return 'Integer',''
 if name.endswith('_date'):return 'Date','yyyy-MM-dd'
 if name.startswith('is_'):return 'Boolean',''
 return 'String',''

def _hop_encoding(value:str):
 normalized=(value or 'UTF-8').strip().lower().replace('_','-')
 return {'utf-8-sig':'UTF-8','utf8-sig':'UTF-8','utf8':'UTF-8','big5':'Big5'}.get(normalized,value or 'UTF-8')

