def static_validate(artifact:dict):
 if str(artifact.get('artifact_type','HPL')).upper()=='HWF':
  root=ET.parse(artifact['path']).getroot();actions=root.findall('actions/action');types=[x.findtext('type') for x in actions];statement=artifact.get('sql','');errors=[]
  if root.tag!='workflow':errors.append('Root element must be workflow')
  if 'SQL' not in types or 'SPECIAL' not in types or 'SUCCESS' not in types:errors.append('Workflow must contain Start, SQL and Success actions')
  if not re.match(r'(?is)^CREATE\s+(EXTERNAL\s+TABLE|FLEX\s+TABLE)',statement.strip()):errors.append('Stage DDL must create only External or Flex Table')
  if re.search(r'(?is)\b(DROP|ALTER|GRANT|REVOKE|DELETE|UPDATE)\b',statement):errors.append('Unsafe SQL keyword in Stage DDL')
  return {'valid':not errors,'errors':errors,'action_types':types,'xml_well_formed':True,'sql':statement,'stage_mode':artifact.get('stage_mode')}
 root=ET.parse(artifact['path']).getroot();types=[x.findtext('type') for x in root.findall('transform')];names=[x.findtext('name') for x in root.findall('transform')]
 errors=[]
 if root.tag!='pipeline':errors.append('Root element must be pipeline')
 required=('CSVInput','FilterRows','TableOutput') if 'CSVInput' in types else ('TableInput','TableOutput')
 for item in required:
  if item not in types:errors.append(f'Missing transform {item}')
 if len(names)!=len(set(names)):errors.append('Transform names must be unique')
 errors.extend(validate_pipeline_graph(root))
 return {'valid':not errors,'errors':errors,'transform_types':types,'transform_names':names,'xml_well_formed':True,'generation_plan':artifact.get('generation_plan')}

def semantic_validate(task:dict,artifact:dict):
 errors=[]
 if len(artifact['columns'])<1:errors.append('No source columns')
 if not task['target_config'].get('schema') or not task['target_config'].get('table'):errors.append('Target schema/table missing')
 return {'valid':not errors,'errors':errors,'policy':'FIRST_10_VALID_ROWS','max_rows':10,'post_write_count':True,'source_columns':artifact['columns'],'target':task['target_config']}

def persist_artifact(db_url:str,task_id:str,artifact:dict):
 artifact_id=uuid.uuid4();primary=Path(artifact['path'])
 related=[]
 for key in ('module_path','workflow_path','hwf_path'):
  value=artifact.get(key)
  if value:related.append(Path(value))
 for key in ('module_paths','workflow_paths','artifact_paths'):
  related.extend(Path(x) for x in (artifact.get(key) or []))
 with psycopg.connect(db_url) as conn:
  with conn.cursor() as cur:
   cur.execute("update platform.hop_artifact set is_current=false where task_id=%s",(task_id,))
   primary_type=str(artifact.get('artifact_type') or ('HWF' if primary.suffix.lower()=='.hwf' else 'HPL')).upper()
   cur.execute("insert into platform.hop_artifact(artifact_id,task_id,artifact_type,version,file_path,checksum,file_size,is_current) values(%s,%s,%s,%s,%s,%s,%s,true)",(artifact_id,task_id,primary_type,artifact['version'],str(primary),artifact['checksum'],artifact['size']))
   seen={str(primary.resolve()).lower()}
   for path in related:
    resolved=str(path.resolve()).lower()
    if resolved in seen or not path.is_file():continue
    seen.add(resolved);child_id=uuid.uuid4();kind='HWF' if path.suffix.lower()=='.hwf' else 'HPL';checksum=hashlib.sha256(path.read_bytes()).hexdigest()
    cur.execute("insert into platform.hop_artifact(artifact_id,task_id,artifact_type,version,parent_artifact_id,file_path,checksum,file_size,is_current) values(%s,%s,%s,%s,%s,%s,%s,%s,true)",(child_id,task_id,kind,artifact['version'],artifact_id,str(path),checksum,path.stat().st_size))
 return str(artifact_id)

