def _safe_ident(value:str):
 if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',value):raise ValueError(f'Unsafe SQL identifier: {value}')
 return value

def table_count(db_url:str,target:dict):
 schema=_safe_ident(target['schema']);table=_safe_ident(target['table'])
 if (target.get('type') or 'POSTGRESQL').upper()=='VERTICA':
  import vertica_python
  cfg={'host':os.getenv('VERTICA_HOST','127.0.0.1'),'port':int(os.getenv('VERTICA_PORT','5433')),'user':os.getenv('VERTICA_USER','dbadmin'),'password':os.getenv('VERTICA_PASSWORD',''),'database':os.getenv('VERTICA_DATABASE',''),'tlsmode':os.getenv('VERTICA_TLSMODE','disable')}
  with vertica_python.connect(**cfg) as conn:
   try:cur=conn.cursor();cur.execute(f'SELECT COUNT(*) FROM "{schema}"."{table}"');return cur.fetchone()[0]
   except Exception:return 0
 with psycopg.connect(db_url) as conn:return conn.execute(sql.SQL('select count(*) from {}.{}').format(sql.Identifier(schema),sql.Identifier(table))).fetchone()[0]

